import{_ as t,o as a,c as o,a1 as r}from"./chunks/framework.DH-rCavj.js";const p=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"policy/privacy.md","filePath":"policy/privacy.md","lastUpdated":1784671567000}'),i={name:"policy/privacy.md"};function n(s,e,c,d,l,h){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p>Effective date: July 21, 2026</p><p>This Privacy Policy explains how BeThere (“we,” “us,” or “our”) collects, uses, stores, and shares information when you use the BeThere website at <a href="https://bethere.ai/" target="_blank" rel="noreferrer">bethere.ai</a>, the BeThere application at <a href="https://buildmate.bethere.ai/" target="_blank" rel="noreferrer">buildmate.bethere.ai</a>, and related BeThere services (collectively, the “Service”).</p><h2 id="_1-information-we-collect" tabindex="-1">1. Information we collect <a class="header-anchor" href="#_1-information-we-collect" aria-label="Permalink to &quot;1. Information we collect&quot;">​</a></h2><p>We collect information in the following categories:</p><ul><li><strong>Account information:</strong> your name, email address, profile image, account identifier, authentication information, and organization or workspace membership.</li><li><strong>Business and configuration information:</strong> the business details, rules, instructions, projects, specialist configurations, and connected-service settings that you provide.</li><li><strong>Service content:</strong> prompts, messages, generated content, files, support requests, and other content submitted through or created with the Service.</li><li><strong>Connected-service data:</strong> information that you authorize BeThere to access from third-party services, including the Google user data described below.</li><li><strong>Usage and device information:</strong> IP address, browser and device type, operating system, referring pages, pages or features used, timestamps, diagnostic data, and cookie or similar-technology data.</li><li><strong>Transaction information:</strong> billing and subscription records. Payment card details are processed by our payment provider and are not stored by BeThere.</li></ul><p>If a business uses BeThere to interact with its own customers or other end users, that business determines what information it asks BeThere to process. The business is responsible for providing required notices and obtaining required consent from its end users.</p><h2 id="_2-how-we-use-information" tabindex="-1">2. How we use information <a class="header-anchor" href="#_2-how-we-use-information" aria-label="Permalink to &quot;2. How we use information&quot;">​</a></h2><p>We use information to:</p><ul><li>provide, operate, secure, and maintain the Service;</li><li>authenticate users and maintain application sessions;</li><li>configure and run the specialists, coordinators, integrations, and workflows you request;</li><li>communicate with you about the Service and provide support;</li><li>monitor performance, diagnose errors, prevent fraud or abuse, and protect users;</li><li>improve Service reliability and user-facing functionality; and</li><li>comply with law and enforce our agreements.</li></ul><p>We do not sell Personal Information. We do not use Google user data for advertising.</p><h2 id="_3-google-api-user-data" tabindex="-1">3. Google API user data <a class="header-anchor" href="#_3-google-api-user-data" aria-label="Permalink to &quot;3. Google API user data&quot;">​</a></h2><p>BeThere connects to Google only after a user authorizes access through Google OAuth. The permissions requested depend on the feature the user chooses to connect.</p><h3 id="google-data-bethere-accesses-and-how-it-is-used" tabindex="-1">Google data BeThere accesses and how it is used <a class="header-anchor" href="#google-data-bethere-accesses-and-how-it-is-used" aria-label="Permalink to &quot;Google data BeThere accesses and how it is used&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Google data</th><th>How BeThere uses it</th></tr></thead><tbody><tr><td>Google account profile, name, profile image, account identifier, and email address</td><td>To sign you in, create and secure your BeThere account, display your account identity, associate an authorized Google connection with the correct BeThere workspace, and communicate about the Service.</td></tr><tr><td>Gmail sending access</td><td>To send messages, such as confirmations and follow-ups, from the Gmail account you authorize and only as directed by the workflows you configure. BeThere does not use Gmail access to read or synchronize your inbox.</td></tr><tr><td>Google Calendar calendars and events</td><td>To find availability and to create, view, update, reschedule, or cancel appointment and reservation events requested through your configured workflows.</td></tr><tr><td>Google Workspace customer, buildings, rooms, and calendar resources</td><td>To discover the authorized organization’s bookable locations and resources, check availability, and reserve rooms or other resources with calendar events.</td></tr><tr><td>Google spreadsheets you select</td><td>To read and update business data in the specific Google Sheets files you choose through the Google file picker. The drive.file permission limits access to files selected for use with BeThere or created by BeThere; BeThere does not browse unrelated Drive files.</td></tr><tr><td>OAuth access tokens, refresh tokens, granted scopes, and authorized-account metadata</td><td>To maintain the connections you authorize and make permitted Google API requests without requiring you to reconnect for every action.</td></tr></tbody></table><h3 id="storage-and-protection" tabindex="-1">Storage and protection <a class="header-anchor" href="#storage-and-protection" aria-label="Permalink to &quot;Storage and protection&quot;">​</a></h3><p>BeThere stores OAuth tokens in a restricted secret store separately from ordinary project configuration. Project files and browser-visible configuration use secret references rather than exposing the token values. We use transport encryption when communicating with Google and apply access controls and other safeguards designed to prevent unauthorized access, use, or disclosure.</p><p>Calendar, Gmail, Workspace resource, and selected spreadsheet data may be processed and retained when needed to complete the workflow you requested, maintain the resulting appointment, message, configuration, or business record, provide support, protect the Service, or comply with law. We retain Google user data only for as long as needed for these purposes and the connected BeThere account. We then delete or de-identify it, subject to limited retention in security records or backups and any legal obligations.</p><h3 id="sharing-and-limited-use" tabindex="-1">Sharing and Limited Use <a class="header-anchor" href="#sharing-and-limited-use" aria-label="Permalink to &quot;Sharing and Limited Use&quot;">​</a></h3><p>We share Google user data only:</p><ul><li>with service providers that process data on our behalf to host, secure, support, and operate BeThere, under contractual confidentiality and data-protection obligations;</li><li>with recipients and services you direct BeThere to contact or update, such as an attendee who receives a calendar invitation or Gmail message;</li><li>when necessary to investigate security issues or abuse;</li><li>when required by applicable law; or</li><li>as part of a merger, acquisition, or sale of assets, subject to applicable notice and consent requirements.</li></ul><p>We do not sell Google user data, share it with advertising platforms or data brokers, use it for personalized or interest-based advertising, use it to determine creditworthiness, or use raw or derived Google Workspace API data to train or improve generalized artificial intelligence or machine-learning models. We do not allow humans to read Google user data except with the user’s affirmative permission for specific data, when necessary for security or support, when required by law, or when the data has been aggregated and de-identified for internal operations.</p><p>BeThere’s use and transfer to any other application of information received from Google APIs will adhere to the <a href="https://developers.google.com/terms/api-services-user-data-policy" target="_blank" rel="noreferrer">Google API Services User Data Policy</a>, including its Limited Use requirements.</p><h3 id="revoke-access-or-request-deletion" tabindex="-1">Revoke access or request deletion <a class="header-anchor" href="#revoke-access-or-request-deletion" aria-label="Permalink to &quot;Revoke access or request deletion&quot;">​</a></h3><p>You can revoke BeThere’s Google access at any time from your <a href="https://myaccount.google.com/connections" target="_blank" rel="noreferrer">Google Account’s third-party connections page</a>. Revocation prevents future access through the revoked authorization but does not by itself delete information previously stored in BeThere.</p><p>To request deletion of Google user data or your BeThere account, email <a href="mailto:contact@bethere.ai" target="_blank" rel="noreferrer">contact@bethere.ai</a> from the email address associated with your account and identify the BeThere workspace or connection to delete. We will verify the request, delete the applicable OAuth tokens and Google user data that we control, and retain only information that we must keep for security, fraud prevention, legal compliance, or the establishment or defense of legal claims. End users of a BeThere customer should direct deletion requests to that customer first.</p><h2 id="_4-how-we-share-information" tabindex="-1">4. How we share information <a class="header-anchor" href="#_4-how-we-share-information" aria-label="Permalink to &quot;4. How we share information&quot;">​</a></h2><p>In addition to the Google-specific sharing described above, we may share information:</p><ul><li>with hosting, analytics, communications, support, payment, and other vendors that help us operate the Service;</li><li>with other members of a workspace according to the permissions configured by that workspace;</li><li>at your direction or with your consent;</li><li>to comply with law, legal process, or governmental requests;</li><li>to protect the rights, safety, and security of BeThere, our users, or others; and</li><li>in connection with a merger, financing, acquisition, reorganization, bankruptcy, or sale of assets.</li></ul><p>Our vendors may use information only to perform services for us and not for their own marketing purposes.</p><h2 id="_5-cookies-and-analytics" tabindex="-1">5. Cookies and analytics <a class="header-anchor" href="#_5-cookies-and-analytics" aria-label="Permalink to &quot;5. Cookies and analytics&quot;">​</a></h2><p>We use necessary cookies to operate features such as authentication and user preferences. With your consent where required, we may use analytics cookies to understand website traffic and improve the Service. You can manage optional cookies through the cookie controls on our website and through your browser settings.</p><h2 id="_6-data-retention-and-security" tabindex="-1">6. Data retention and security <a class="header-anchor" href="#_6-data-retention-and-security" aria-label="Permalink to &quot;6. Data retention and security&quot;">​</a></h2><p>We retain Personal Information for as long as necessary to provide the Service, fulfill the purposes described in this Policy, resolve disputes, enforce agreements, and meet legal, tax, accounting, and security obligations. Retention depends on the type of information, why we collected it, and applicable requirements. When information is no longer needed, we delete or de-identify it, subject to limited backup retention.</p><p>We use reasonable administrative, technical, and physical safeguards designed to protect information. No method of electronic transmission or storage is completely secure, so we cannot guarantee absolute security.</p><h2 id="_7-your-choices-and-privacy-rights" tabindex="-1">7. Your choices and privacy rights <a class="header-anchor" href="#_7-your-choices-and-privacy-rights" aria-label="Permalink to &quot;7. Your choices and privacy rights&quot;">​</a></h2><p>Depending on where you live, you may have the right to access, correct, delete, or obtain a copy of your Personal Information; restrict or object to certain processing; or withdraw consent. You may also have the right to appeal our response or complain to a data-protection authority.</p><p>To exercise a privacy right, email <a href="mailto:contact@bethere.ai" target="_blank" rel="noreferrer">contact@bethere.ai</a>. We may need to verify your identity and authority to make the request. We will not discriminate against you for exercising applicable privacy rights.</p><h2 id="_8-international-data-transfers" tabindex="-1">8. International data transfers <a class="header-anchor" href="#_8-international-data-transfers" aria-label="Permalink to &quot;8. International data transfers&quot;">​</a></h2><p>BeThere is based in the United States. We and our service providers may process information in the United States and other countries where privacy laws may differ from those in your jurisdiction. Where required, we use appropriate safeguards for international transfers.</p><h2 id="_9-children" tabindex="-1">9. Children <a class="header-anchor" href="#_9-children" aria-label="Permalink to &quot;9. Children&quot;">​</a></h2><p>The Service is not directed to children under 13, and we do not knowingly collect Personal Information from children under 13. If you believe a child has provided Personal Information to us, contact us so we can take appropriate action.</p><h2 id="_10-third-party-services" tabindex="-1">10. Third-party services <a class="header-anchor" href="#_10-third-party-services" aria-label="Permalink to &quot;10. Third-party services&quot;">​</a></h2><p>The Service may link to or integrate with third-party services. Their handling of information is governed by their own terms and privacy policies. This Policy governs information processed through BeThere.</p><h2 id="_11-changes-to-this-policy" tabindex="-1">11. Changes to this Policy <a class="header-anchor" href="#_11-changes-to-this-policy" aria-label="Permalink to &quot;11. Changes to this Policy&quot;">​</a></h2><p>We may update this Policy as the Service or legal requirements change. We will update the effective date above and provide additional notice when required. If we materially change how we use Google user data, we will notify affected users and obtain consent when required before using the data for the new purpose.</p><h2 id="_12-contact-us" tabindex="-1">12. Contact us <a class="header-anchor" href="#_12-contact-us" aria-label="Permalink to &quot;12. Contact us&quot;">​</a></h2><p>BeThere Privacy <a href="mailto:contact@bethere.ai" target="_blank" rel="noreferrer">contact@bethere.ai</a></p><p>For the terms governing use of the Service, see the <a href="/policy/terms">BeThere Terms of Service</a>.</p>',49)]))}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
